  const [state, setState] = useState("Todos");
  const [modalUser, setModalUser] = useState<TeamUser | null | undefined>(undefined);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => { let mounted = true; fetch("/api/admin/users", { cache: "no-store" }).then(async (response) => { if (!mounted) return; if (response.ok) { const result = await response.json() as { users: TeamUser[] }; setUsers(result.users); } setLoading(false); }).catch(() => { if (mounted) setLoading(false); }); return () => { mounted = false; }; }, []);
  const filtered = useMemo(() => users.filter((user) => { const text = `${user.name} ${user.documentNumber || ""} ${user.email}`.toLowerCase(); return text.includes(query.toLowerCase()) && (role === "Todos" || user.role === role) && (state === "Todos" || state === "Activos" && user.active || state === "Inactivos" && !user.active); }), [users, query, role, state]);
  const saveUser = async (payload: { name: string; documentNumber: string; email: string; phone: string; password: string; role: string; active: boolean }, id?: string) => {
    setError("");
    const response = await fetch(id ? `/api/admin/users/${id}` : "/api/admin/users", { method: id ? "PATCH" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
    const result = await response.json() as { user?: TeamUser; error?: string }; if (!response.ok || !result.user) { setError(result.error || "No fue posible guardar los cambios."); return false; } setUsers((current) => id ? current.map((user) => user.id === id ? result.user! : user) : [...current, result.user!].sort((a, b) => a.name.localeCompare(b.name))); setModalUser(undefined); return true;
  };
